            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "De seu calmo esconderijo, o ouro vem, dócil e ingênuo; torna-se pó, folha, barra, prestígio, poder, engenho... É tão claro! - e turva tudo: honra, amor e pensamento", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "aprendi com as primaveras/a deixar-me cortar e a voltar sempre inteira.", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "O vento é o mesmo:/mas sua resposta é diferente, em cada folha./ Somente a árvore seca fica imóvel,/entre borboletas e pássaros.", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "O vento vem vindo de longe,/a noite se curva de frio;/debaixo da água vai morrendo/meu sonho, dentro de um navio...", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "Liberdade, essa palavra que o sonho humano alimenta, que não há ninguém que explique e ninguém que não entenda.", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "Entre mim e mim há vastidões bastantes para a navegação dos meus desejos afligidos", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "Ó meu Deus, isto é a minha alma: qualquer coisa que flutua sobre este corpo efêmero e precário, como o vento largo do oceano sobre a areia passiva e inúmera...", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "A primavera chegará, mesmo que ninguém mais saiba seu nome, nem acredite no calendário, nem possua jardim para recebê-la.", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "Permita que eu feche os meus olhos, pois é muito longe e tão tarde! Pensei que era apenas demora, e cantando pus-me a esperar-te.", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "Sobre o tempo vem mais tempo. Mandam sempre os que são grandes: e é grandeza de ministros roubar hoje como dantes", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "Quem tivesse um amor, nesta noite de lua, para pensar um belo pensamento e pousá-lo no vento!... Quem tivesse um amor - longe, certo e impossível - para se ver chorando, e gostar de chorar, e adormecer de lágrimas e luar!", Author = "Cecília Meireles" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Cecília_Meireles", Text = "Quero ver-te à luz do dia para saber se é verdade o que a noite me dizia com tanta seguridade.", Author = "Cecília Meireles" },
